def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    # Find the separate tiled objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            components.append((r0, r1, c0, c1))

    # The inner portion of each tile carries its color/pattern; ignore its border.
    tile_colors = []
    for r0, r1, c0, c1 in components:
        colors = set()
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if grid[r][c] != 0:
                    colors.add(grid[r][c])
        if colors:
            tile_colors.append(colors)

    counts = {}
    for colors in tile_colors:
        for color in colors:
            counts[color] = counts.get(color, 0) + 1
    if not counts:
        return [row[:] for row in grid]

    most_common = max(counts.values())
    signals = {color for color, count in counts.items() if count < most_common}

    out = [row[:] for row in grid]

    # Connect aligned occurrences of each minority color, filling only empty cells.
    for color in signals:
        for r in range(h):
            xs = [c for c in range(w) if grid[r][c] == color]
            if len(xs) >= 2:
                for c in range(min(xs), max(xs) + 1):
                    if out[r][c] == 0:
                        out[r][c] = color

        for c in range(w):
            ys = [r for r in range(h) if grid[r][c] == color]
            if len(ys) >= 2:
                for r in range(min(ys), max(ys) + 1):
                    if out[r][c] == 0:
                        out[r][c] = color

    return out
